const raw = $input.first().json;
const body = raw.body ?? raw;
const { origin, destination, dates, apiKey } = body;
return dates.map((d) => ({
  json: {
    _serpUrl: 'https://serpapi.com/search?engine=google_flights&departure_id=' + origin + '&arrival_id=' + destination + '&outbound_date=' + d.date + '&type=2&hl=th&currency=THB&api_key=' + apiKey,
    date: d.date,
    dayOfWeek: d.dayOfWeek,
    displayDate: d.displayDate,
  },
}));

function minutesToThai(min) {
  const h = Math.floor(min / 60);
  const m = min % 60;
  return m > 0 ? (h + 'ช. ' + m + 'น.') : (h + 'ช.');
}
function parsePrice(p) {
  return Number(String(p || '').replace(/,/g, ''));
}
const results = [];
for (const item of $input.all()) {
  try {
    const d = item.json;
    const all = (d.best_flights || []).concat(d.other_flights || []);
    const valid = all.filter(f => { const p = parsePrice(f.price); return !isNaN(p) && p > 0; });
    if (valid.length === 0) continue;
    const cheapest = valid.reduce((a, b) => (parsePrice(a.price) < parsePrice(b.price) ? a : b));
    const price = parsePrice(cheapest.price);
    results.push({
      date: d.date,
      dayOfWeek: d.dayOfWeek,
      displayDate: d.displayDate,
      price: price,
      airline: cheapest.flights[0].airline,
      airlineLogo: cheapest.airline_logo || (cheapest.flights[0] && cheapest.flights[0].airline_logo) || '',
      duration: minutesToThai(cheapest.total_duration),
      stops: Math.min(cheapest.flights.length - 1, 1),
      googleFlightsUrl: (d.search_metadata && d.search_metadata.google_flights_url) || '',
    });
  } catch (e) {
    // skip item
  }
}
results.sort((a, b) => a.price - b.price);
return [{ json: { results: results } }];
